begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values ('66666666-6666-4666-8666-666666666666','customer-a@example.test'),('77777777-7777-4777-8777-777777777777','customer-b@example.test');
set local role authenticated;
select set_config('request.jwt.claim.sub','66666666-6666-4666-8666-666666666666',true);
insert into profiles(id,"displayName") values ('customer-budget','Existing budget');
select daywise_income('customer-budget',to_char(current_date,'YYYY-MM'),1234567,'default');
select spendense_save_customer('{"category":"salaried","pattern":"regular","frequency":"weekly","rateMinor":10001,"workDays":[1,2,3,4,5]}','11111111-1111-4111-8111-111111111111',0,'customer-budget',to_char(current_date,'YYYY-MM'),null);
select is((select count(*) from customer_financial_preferences),1::bigint,'One preferences row per account');
select is((select "monthlyIncomeMinor"::bigint from monthly_plans where "profileId"='customer-budget' and "yearMonth"=to_char(current_date,'YYYY-MM')),1234567::bigint,'Completing personal details preserves existing allocation');
select ok((select "onboardingComplete" from profiles where id='customer-budget'),'Completion marks selected existing budget ready');
select spendense_save_customer('{"category":"salaried","pattern":"regular","frequency":"weekly","rateMinor":10001,"workDays":[1,2,3,4,5]}','11111111-1111-4111-8111-111111111111',0,'customer-budget',to_char(current_date,'YYYY-MM'),999999);
select is((select revision from customer_financial_preferences),1::bigint,'Retrying the same completed request does not repeat financial writes');
select throws_ok($q$select spendense_save_customer('{"category":"salaried","pattern":"regular","frequency":"monthly","rateMinor":0,"workDays":[]}','22222222-2222-4222-8222-222222222222',0)$q$,'40001',null,'Stale preferences cannot overwrite new revision');
select throws_ok($q$update customer_financial_preferences set configuration='{"category":"salaried","pattern":"regular","frequency":"daily","rateMinor":10,"workDays":[]}'$q$,'23514',null,'Daily schedule cannot be empty');
select throws_ok($q$update customer_financial_preferences set configuration='{"category":"salaried","pattern":"regular","frequency":"daily","rateMinor":10,"workDays":[1,1]}'$q$,'23514',null,'Paid days cannot be duplicated');
select throws_ok($q$update customer_financial_preferences set configuration='{"category":"business","pattern":"seasonal","frequency":"weekly","rateMinor":10,"workDays":[]}'$q$,'23514',null,'Business uses monthly personal take-home');
select throws_ok($q$update customer_financial_preferences set configuration='{"category":null,"pattern":"regular","frequency":"monthly","rateMinor":0,"workDays":[]}'$q$,'23514',null,'Null category is rejected');
select throws_ok($q$select spendense_save_customer('{"category":"salaried","pattern":"regular","frequency":"monthly","rateMinor":0,"workDays":[]}','22222222-2222-4222-8222-222222222222',1,'customer-budget',to_char(current_date,'YYYY-MM'),100,'month',0,false)$q$,'40001',null,'Income changed during review cannot be overwritten');
select spendense_save_customer('{"category":"freelancer","pattern":"variable","frequency":"monthly","rateMinor":1500000,"workDays":[]}','22222222-2222-4222-8222-222222222222',1,'customer-budget',to_char(current_date,'YYYY-MM'),1500001,'month',1234567,false);
select is((select "monthlyIncomeMinor"::bigint from monthly_plans where "profileId"='customer-budget' and "yearMonth"=to_char(current_date,'YYYY-MM')),1500001::bigint,'Explicit confirmed amount retains exact paise');
select is((select count(*) from profiles),1::bigint,'Editing preferences creates no duplicate budget');
select set_config('request.jwt.claim.sub','77777777-7777-4777-8777-777777777777',true);
select is((select count(*) from customer_financial_preferences),0::bigint,'Second account cannot read first account preferences');
with changed as (update customer_financial_preferences set revision=99 returning *) select is((select count(*) from changed),0::bigint,'Second account cannot update preferences');
with removed as (delete from customer_financial_preferences returning *) select is((select count(*) from removed),0::bigint,'Second account cannot delete preferences');
select throws_ok($q$insert into customer_financial_preferences(owner_id,configuration,last_request) values ('66666666-6666-4666-8666-666666666666','{"category":"other","pattern":"variable","frequency":"monthly","rateMinor":0,"workDays":[]}','33333333-3333-4333-8333-333333333333')$q$,'42501',null,'Cannot insert for another owner');
select throws_ok($q$select spendense_save_customer('{"category":"other","pattern":"variable","frequency":"monthly","rateMinor":0,"workDays":[]}','33333333-3333-4333-8333-333333333333',0,'customer-budget',to_char(current_date,'YYYY-MM'),null)$q$,'42501',null,'Cannot complete another owner budget');
select set_config('request.jwt.claim.sub','66666666-6666-4666-8666-666666666666',true);
select throws_ok($q$select spendense_save_customer('{"category":"salaried","pattern":"regular","frequency":"monthly","rateMinor":100,"workDays":[]}','44444444-4444-4444-8444-444444444444',2,'customer-budget',to_char(current_date-interval '1 month','YYYY-MM'),100,'month',100,false)$q$,'22023',null,'New onboarding RPC cannot rewrite a past month');
select is((select revision from customer_financial_preferences),2::bigint,'Rejected past income write leaves preferences revision unchanged');
select throws_ok($q$update customer_financial_preferences set configuration=configuration || '{"full_name":"Duplicate identity"}'$q$,'23514',null,'Identity cannot be duplicated in structured financial configuration');
select throws_ok($q$update customer_financial_preferences set configuration=jsonb_set(configuration,'{rateMinor}','100000000001')$q$,'23514',null,'Server rejects amounts beyond the financial limit');
with removed as (delete from customer_financial_preferences returning *) select is((select count(*) from removed),1::bigint,'Owner can delete own preferences under DELETE policy');
insert into customer_financial_preferences(configuration,last_request) values ('{"category":"other","pattern":"variable","frequency":"monthly","rateMinor":0,"workDays":[]}','55555555-5555-4555-8555-555555555555');
select is((select count(*) from customer_financial_preferences),1::bigint,'Owner can insert own valid configuration under INSERT policy');
set local role anon;
select throws_ok($q$select * from customer_financial_preferences$q$,'42501',null,'Anonymous preferences read denied');
select throws_ok($q$select spendense_save_customer('{}','33333333-3333-4333-8333-333333333333',0)$q$,'42501',null,'Anonymous RPC denied');
reset role;
select is((select prosecdef from pg_proc where oid='public.spendense_save_customer(jsonb,uuid,bigint,text,public.daywise_month,public.daywise_minor,text,public.daywise_minor,boolean)'::regprocedure),false,'RPC uses caller RLS permissions');
select * from finish();
rollback;
